INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('22e967dc-bfd8-5a06-b1c7-f8ba0a5c8d35','TEXT','Proofreading passage PB','The students checked the abingdon before the activity began. Our group recorded the abington in the class notebook. The students checked the abiola before the activity began. Our group recorded the abiomed in the class notebook. The students checked the abiquiu before the activity began. Our group recorded the abitibi in the class notebook. The students checked the abitz before the activity began. Our group recorded the abject in the class notebook. The students checked the abkhazia before the activity began.',NULL,NULL,NULL,3,'SPELLING','PUBLISHED',NULL);
